dash.calc('totals',{inputs:['orders'],title:'Order totals',description:'Order counts and payout totals from the order list.',
 fn:(orders)=>{const sum=f=>orders.filter(f).reduce((s,r)=>s+Number(r.payout||0),0);const del=orders.filter(r=>r.status==='Delivered').length;
  return [{orders:orders.length,delivered:del,open:orders.length-del,billed:sum(()=>true),received:sum(r=>r.payout_status==='Received'),pending:sum(r=>r.payout_status==='Pending')}];}});
dash.calc('by_brand',{inputs:['orders'],title:'Orders by brand',description:'Order count and payout total per brand.',
 fn:(orders)=>{const m=new Map();orders.forEach(r=>{const x=m.get(r.brand)||{brand:r.brand,orders:0,sale_value:0};x.orders++;x.sale_value+=Number(r.payout||0);m.set(r.brand,x);});return [...m.values()].sort((a,b)=>b.sale_value-a.sale_value);}});
dash.calc('actions',{inputs:['orders'],title:'Your to-dos',description:'Orders waiting on the client: payment due, address needed, out for delivery.',
 fn:(orders)=>{const out=[];
  orders.forEach(r=>{if(r.payout_status==='Pending')out.push({item:(r.order_no?r.order_no+' ':'')+r.item,kind:'Payment due',detail:'₹'+r.payout+' to pay'});
   if(Number(r.stage)===7)out.push({item:(r.order_no?r.order_no+' ':'')+r.item,kind:'Address needed',detail:'Open the Address tab and paste your address'});
   if(Number(r.stage)===8)out.push({item:(r.order_no?r.order_no+' ':'')+r.item,kind:'Arriving today',detail:'Out for delivery, keep your phone handy'});});
  return out;}});
dash.calc('by_month',{inputs:['orders'],title:'Spend by month',description:'Order value and count per order month.',
 fn:(orders)=>{const m=new Map();orders.forEach(r=>{if(!r.order_date)return;const k=String(r.order_date).slice(0,7);const x=m.get(k)||{month:k,orders:0,value:0};x.orders++;x.value+=Number(r.payout||0);m.set(k,x);});return [...m.values()].sort((a,b)=>a.month<b.month?-1:1);}});
dash.calc('by_cat',{inputs:['orders'],title:'Spend by category',description:'Order value grouped as Bags, Shoes, Accessories or Other from the item name.',
 fn:(orders)=>{const cat=s=>{s=String(s).toLowerCase();if(/sneaker|slide|sandal|shoe|boot|adizero|speedcat|chukka|loafer|flip/.test(s))return 'Shoes';if(/bag|tote|crossbody|satchel|hobo|shoulder|backpack|messenger|carryall/.test(s))return 'Bags';if(/wallet|belt|wristlet|watch|card|keychain|scarf/.test(s))return 'Accessories';return 'Other';};
  const m={};orders.forEach(r=>{const c=cat(r.item);const x=m[c]||{category:c,orders:0,value:0};x.orders++;x.value+=Number(r.payout||0);m[c]=x;});return Object.values(m).sort((a,b)=>b.value-a.value);}});
