 fab.addEventListener('click',open);document.getElementById('chat-new').addEventListener('click',()=>{chat.msgs=[];chat.last=null;document.getElementById('chat-msgs').textContent='';chatAdd('a','New conversation. What would you like to know?');});document.getElementById('chat-x').addEventListener('click',()=>{box.hidden=true;fab.hidden=false;chat.open=false;});
 const sug=document.getElementById('chat-sug');['Where are my orders?','What do I owe?','How does ordering work?','Payment & cancellation','Tracking links'].forEach(s=>{const b=document.createElement('button');b.type='button';b.className='chip';b.textContent=s;b.addEventListener('click',()=>ask(s));sug.appendChild(b);});
