function renderMini(o){const w=document.getElementById('mini');if(o.status!=='ok'){w.className='mini';return;}const open=o.data.filter(r=>r.status!=='Delivered'&&Number(r.stage||1)<9);const due=o.data.filter(r=>r.payout_status==='Pending').reduce((s,r)=>s+Number(r.payout||0),0);const nx=open.filter(r=>r.eta_date).sort((a,b)=>a.eta_date<b.eta_date?-1:1)[0];w.textContent='';const add=(k,v)=>{const s=document.createElement('span');s.textContent=k+' ';const b=document.createElement('b');b.textContent=v;s.appendChild(b);w.appendChild(s);};add('Open',String(open.length));add('Due','₹'+fmt(due));if(nx)add('Next ETA',fd(nx.eta_date));w.className='mini';addEventListener('scroll',()=>{w.classList.toggle('show',scrollY>420);},{passive:true});}
function renderGantt(o){const w=document.getElementById('gantt');w.textContent='';if(o.status!=='ok')return;const open=o.data.filter(r=>r.status!=='Delivered'&&Number(r.stage||1)<9&&(r.order_date||r.eta_date));if(!open.length){w.textContent='No open orders to plot.';w.classList.add('lbl');return;}
 const ds=[];open.forEach(r=>{if(r.order_date)ds.push(new Date(r.order_date));if(r.eta_date)ds.push(new Date(r.eta_date));});ds.push(new Date());const min=new Date(Math.min(...ds)),max=new Date(Math.max(...ds));max.setDate(max.getDate()+2);min.setDate(min.getDate()-1);const span=max-min||1;const pos=d=>Math.max(0,Math.min(100,100*(new Date(d)-min)/span));
 open.sort((a,b)=>String(a.order_date||'')<String(b.order_date||'')?-1:1).forEach(r=>{const nm=document.createElement('div');nm.className='nm';nm.textContent=(r.order_no||'')+' '+r.item;nm.title=r.item;const lane=document.createElement('div');lane.className='lane';const s=r.order_date?pos(r.order_date):pos(new Date()),e=r.eta_date?pos(r.eta_date):Math.min(100,s+10);const bar=document.createElement('i');bar.style.left=s+'%';bar.style.width=Math.max(1,e-s)+'%';lane.appendChild(bar);const st=Number(r.stage||1);const done=document.createElement('i');done.className='done';done.style.left=s+'%';done.style.width=Math.max(0,(e-s)*Math.min(1,(st-1)/8))+'%';lane.appendChild(done);if(r.eta_date){const em=document.createElement('em');em.style.left=e+'%';em.title='ETA '+fd(r.eta_date);lane.appendChild(em);}const td=document.createElement('span');td.className='today';td.style.left=pos(new Date())+'%';lane.appendChild(td);w.appendChild(nm);w.appendChild(lane);});
 const ax=document.createElement('div');ax.className='ax';[min,new Date((min.getTime()+max.getTime())/2),max].forEach(d=>{const s=document.createElement('span');s.textContent=fd(d.toISOString().slice(0,10));ax.appendChild(s);});w.appendChild(ax);}
function renderQuotes(){const w=document.getElementById('quotes');w.textContent='';const list=Object.entries(photos.quotes).map(([id,v])=>Object.assign({id},v)).sort((a,b)=>String(b.at||'')<String(a.at||'')?-1:1);
 if(!list.length){const s=document.createElement('span');s.className='lbl';s.textContent='Nothing quoted yet. Use Ask for a quote in Help.';w.appendChild(s);}
 list.forEach(q=>{const row=document.createElement('div');row.className='q';const st=document.createElement('span');st.className='qs';st.textContent=q.status||'Quoted';st.style.color=q.status==='Ordered'?'var(--gold-2)':(q.status==='Expired'?'var(--muted)':'var(--ivory)');const t=document.createElement('div');t.style.flex='1';const n=document.createElement('div');n.textContent=q.item;const v=document.createElement('div');v.className='qv';v.appendChild(money(Number(q.price||0)));const s=document.createElement('div');s.className='lbl';s.textContent=(q.note?q.note+' · ':'')+(q.valid?'Valid till '+fd(q.valid):'')+(q.at?' · quoted '+fd(q.at):'');t.appendChild(n);t.appendChild(v);t.appendChild(s);row.appendChild(st);row.appendChild(t);
  {const o2=dash.data('orders');if(o2.status==='ok'){const dup=o2.data.find(x=>x.item.toLowerCase()===String(q.item).toLowerCase());if(dup){const dw=document.createElement('div');dw.className='lbl';dw.textContent='Note: you already have '+(dup.order_no||'this piece')+' ('+(stName(dup,dup.stage)||dup.status)+').';t.appendChild(dw);}}}
  if(window.__lxQuoteRow)window.__lxQuoteRow(q,row,t);else if((q.status||'Quoted')==='Quoted'){row.appendChild(copyBtn('Accept',()=>'Hi Luxella, I accept the quote for '+q.item+' at ₹'+fmt(q.price)+'. Please go ahead.\n— '+CLIENT(),'btn2'));}
  if(photos.canEdit){const sel=document.createElement('select');sel.className='inp owner';sel.style.maxWidth='9rem';['Quoted','Approved','Ordered','Expired'].forEach(x=>{const o=document.createElement('option');o.textContent=x;o.selected=x===(q.status||'Quoted');sel.appendChild(o);});sel.addEventListener('change',async()=>{try{await photos.db.doc('quotes/'+q.id).set(Object.assign({},q,{status:sel.value}));delete q.id;}catch(e){alertMsg('Could not update.');}});row.appendChild(sel);const rm=document.createElement('button');rm.type='button';rm.className='addph owner';rm.textContent='Remove';rm.addEventListener('click',async()=>{try{await photos.db.doc('quotes/'+q.id).delete();}catch(e){}});row.appendChild(rm);}
  w.appendChild(row);});
 if(photos.canEdit){const f=document.createElement('div');f.className='owner';f.style.cssText='display:grid;grid-template-columns:repeat(auto-fit,minmax(8rem,1fr));gap:8px;margin-top:12px';const it=document.createElement('input');it.className='inp';it.placeholder='Item';const pr=document.createElement('input');pr.className='inp';pr.type='number';pr.placeholder='Price ₹';const vd=document.createElement('input');vd.className='inp';vd.type='date';const nt=document.createElement('input');nt.className='inp';nt.placeholder='Note (size, colour)';const sh=document.createElement('input');sh.className='inp';sh.type='number';sh.placeholder='Other charges ₹ (0 = included)';const ad2=document.createElement('input');ad2.className='inp';ad2.placeholder='Advance e.g. 50% or ₹5000';const wn=document.createElement('input');wn.className='inp';wn.placeholder='Delivery window e.g. 18-25 days from order';const b=document.createElement('button');b.type='button';b.className='addph';b.textContent='Post quote';b.addEventListener('click',async()=>{if(!it.value.trim()||!pr.value)return;try{await photos.db.collection('quotes').add({item:it.value.trim(),price:Number(pr.value),shipping:Number(sh.value||0),total:Number(pr.value)+Number(sh.value||0),advance:ad2.value.trim(),window:wn.value.trim(),valid:vd.value,note:nt.value.trim(),status:'Quoted',at:new Date().toISOString().slice(0,10)});it.value=pr.value=vd.value=nt.value=sh.value=ad2.value=wn.value='';alertMsg('Quote posted.');}catch(e){alertMsg('Could not post.');}});[it,pr,sh,vd,nt,ad2,wn,b].forEach(x=>f.appendChild(x));w.appendChild(f);}}
