function trkLine(r,st,aud){const useLocal=st>=8||aud==='cust';const no=useLocal?r.local_tracking:r.intl_tracking_no,slug=useLocal?r.local_courier_slug:r.intl_courier_slug,cr=useLocal?r.local_courier:r.intl_courier;if(!no)return '';return '\nTrack here: '+trackUrl(no,slug)+(cr?' ('+cr+' '+no+')':' ('+no+')');}
function fillT(t,r,name,st,aud){const eta=r.eta_date||(predicted(r)||{}).date;return t.replace('{n}',name?' '+name:'').replace(/\{item\}/g,r.item).replace('{f}',CLIENT().split(' ')[0]).replace('{ref}','Ref. '+(r.order_no||'')).replace('{eta}',eta&&st<8?' Expected by '+fd(eta)+(r.eta_date?'':' (estimate)')+'.':'').replace('{trk}',trkLine(r,st,aud)).replace('{pay}',r.payout_status==='Pending'?' ₹'+fmt(r.payout)+' is pending whenever convenient.':'');}
function genMsg(r,aud,st,name,custom,full){const biz=BIZ()||CLIENT().split(' ')[0];let m;if(aud==='cust'){let t;if(full==='ultra'){m=fillT(ULTRA[st]||ULTRA[1],r,name,st,'cust');}else if(mgOpt.lang==='dv'){m=fillT(CUST_DV[st]||CUST_DV[1],r,name,st,'cust');}else if(mgOpt.tone==='pro'){t=PRO_T[st]||PRO_T[1];m=fillT(t,r,name,st,'cust');}else{const T=mgOpt.lang==='hi'?CUST_HI:CUST_T;t=T[st]||T[1];m=fillT(full===true?t[1]:t[0],r,name,st,'cust');}if(mgOpt.emoji&&EMO[st])m=m.replace(/([.!])(\n|$)/,'$1 '+EMO[st]+'$2');}else{m=fillT(ME_T[st]||ME_T[1],r,name,st,'me');}
 if(custom&&custom.trim())m+='\n'+custom.trim();if(aud==='cust')m=m.replace(/\s?#\d{4}\b/g,'').replace(/Ref\. ?/g,'');return m+'\n— '+(aud==='cust'?SIGN():'Luxella');}
