function renderWeek(o){const w=document.getElementById('week');w.textContent='';if(o.status!=='ok')return;const now=Date.now(),in7=now+7*864e5;const items=[];
 o.data.forEach(r=>{const st=Number(r.stage||1);if(st===6){items.push({at:new Date().toISOString().slice(0,10),k:'Address needed soon',it:r});}const pr=predicted(r);if(pr&&!r.eta_date&&new Date(pr.date)<=in7)items.push({at:pr.date,k:'Likely to arrive (est.)',it:r});});
 o.data.forEach(r=>{if(r.eta_date&&r.status!=='Delivered'&&Number(r.stage)<9){const t=new Date(r.eta_date).getTime();if(t<=in7)items.push({at:r.eta_date,k:t<now?'Overdue ETA':'Expected',it:r});}if(Number(r.stage)===7)items.push({at:new Date().toISOString().slice(0,10),k:'Address needed',it:r});if(r.payout_status==='Pending')items.push({at:new Date().toISOString().slice(0,10),k:'Payment due',it:r});});
 if(!items.length){w.textContent='Nothing due this week.';w.classList.add('lbl');return;}w.classList.remove('lbl');
 items.sort((a,b)=>a.at<b.at?-1:1).forEach(x=>{const it=document.createElement('div');it.className='it';const d=document.createElement('span');d.className='dot';d.style.background=x.k==='Payment due'||x.k==='Overdue ETA'?'var(--wine)':'var(--gold)';const t=document.createElement('span');t.textContent=x.k+': '+(x.it.order_no||'')+' '+x.it.item;const sm=document.createElement('small');sm.textContent=fd(x.at)+' · '+rel(x.at);t.appendChild(sm);t.style.cursor='pointer';t.addEventListener('click',()=>openDrawer(x.it));it.appendChild(d);it.appendChild(t);if(x.k==='Payment due'){const pb=payBtn(x.it,'btn2');if(pb){pb.style.marginLeft='auto';it.appendChild(pb);}}w.appendChild(it);});}
function payRecords(r){return (photos.payrec[pslug(r.item)]&&photos.payrec[pslug(r.item)].items)||[];}
function paidAmt(r){const rec=payRecords(r);if(rec.length)return rec.reduce((s,x)=>s+Number(x.amount||0),0);return r.payout_status==='Received'?Number(r.payout||0):0;}
function recordPaymentUI(r){const w=document.createElement('div');w.className='owner';w.style.cssText='display:flex;gap:6px;flex-wrap:wrap;margin-top:6px';const am=document.createElement('input');am.className='inp';am.type='number';am.placeholder='Amount';am.style.maxWidth='7rem';const dt=document.createElement('input');dt.className='inp';dt.type='date';dt.style.maxWidth='9rem';const me=document.createElement('select');me.className='inp';['UPI','Bank transfer','Cash','Other'].forEach(x=>{const o=document.createElement('option');o.textContent=x;me.appendChild(o);});const b=document.createElement('button');b.type='button';b.className='addph';b.textContent='Record';b.addEventListener('click',async()=>{if(!am.value)return;const key=pslug(r.item);const cur=payRecords(r);try{await photos.db.doc('payrec/'+key).set({order:r.item,items:cur.concat([{amount:Number(am.value),at:dt.value||new Date().toISOString().slice(0,10),method:me.value}])});alertMsg('Payment recorded.');}catch(e){alertMsg('Could not record.');}});[am,dt,me,b].forEach(x=>w.appendChild(x));return w;}
function ownerEditor(parent,fields,path,label){if(!photos.canEdit)return;const row=document.createElement('div');row.className='owner';row.style.cssText='display:grid;gap:8px;margin-top:12px';const ins=fields.map(f=>{const i=document.createElement(f.multi?'textarea':'input');i.className='inp';i.placeholder=f.ph;i.value=f.val||'';if(f.multi)i.rows=5;row.appendChild(i);return [f.key,i];});const b=document.createElement('button');b.type='button';b.className='addph';b.textContent=label;b.addEventListener('click',async()=>{const d={};ins.forEach(([k,i])=>d[k]=i.value.trim());d.at=new Date().toISOString().slice(0,10);try{await photos.db.doc(path).set(d);alertMsg('Saved.');}catch(e){alertMsg('Could not save.');}});row.appendChild(b);parent.appendChild(row);}
function renderTerms(){const w=document.getElementById('terms');w.textContent='';const t=photos.terms;
 const el=(tag,cls,txt)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(txt!=null)e.textContent=txt;return e;};
 if(t&&t.parts){
  if(t.intro)w.appendChild(el('p','tintro',t.intro));
  if(t.short&&t.short.length){const d=el('details','tpart');d.open=true;const s=el('summary');s.appendChild(el('span','tnum','00'));s.appendChild(el('span',null,'The short version'));d.appendChild(s);const g=el('div','tshort');t.short.forEach(([k,v])=>{g.appendChild(el('div','tk',k));g.appendChild(el('div','tv',v));});d.appendChild(g);w.appendChild(d);}
  t.parts.forEach(p=>{const d=el('details','tpart');const s=el('summary');s.appendChild(el('span','tnum',p.part));s.appendChild(el('span',null,p.title));d.appendChild(s);
   p.sections.forEach(sec=>{const sd=el('details','tsec');const ss=el('summary');ss.appendChild(el('span','tnum',String(sec.n)));ss.appendChild(el('span',null,sec.title));sd.appendChild(ss);if(sec.lead)sd.appendChild(el('p','tlead',sec.lead));(sec.body||[]).forEach(b=>sd.appendChild(el('p','tbody',b)));d.appendChild(sd);});
   w.appendChild(d);});
  if(t.closing)w.appendChild(el('p','tclose',t.closing));
  const by=el('div','lbl','Luxella · '+(t.title||'Terms')+(t.edition?' · '+t.edition:'')+' · Last revised '+fd(t.at));by.style.marginTop='14px';w.appendChild(by);
  return;}
 if(t&&t.text){w.textContent=t.text;const by=el('div','lbl','Last revised '+fd(t.at));by.style.marginTop='10px';w.appendChild(by);}
 else w.appendChild(el('span','lbl','Terms will be published here.'));}
