 rows.forEach(r=>{const amt=Number(r.payout||0);const paid=paidAmt(r);bal+=amt-paid;const tr=document.createElement('tr');const add=(t,c)=>{const td=document.createElement('td');if(c)td.className=c;td.textContent=t;tr.appendChild(td);};add(r.order_date?fd(r.order_date):'—');add(r.order_no||'—');add(r.item);add(fmt(amt),'n');add(paid?fmt(paid):'—','n');add(fmt(bal),'n bal');tap(tr,()=>openDrawer(r),'Open order');tb.appendChild(tr);lines.push([r.order_date||'',r.order_no||'',r.item,amt,paid,bal].join(' | '));});
