  const t1=add(st>=3?'Shipped':'Pending');seg(t1,st>=3,st<3);const t2=add(local?'—':(st>=5?'Departed':(st>=4?'Received':'Awaiting')));if(!local)seg(t2,st>=5,st===4);const t3=add(st>=8?'Out for delivery':(st>=6?'Landed':'In transit'));seg(t3,st>=6,st===5);
