 const G=(k,v,s,go)=>{const d=g(k,v,s);if(go)tap(d,()=>goTab(go[0],go[1]));return d;};
 const dates=rows.map(r=>r.order_date).filter(Boolean).sort();const since=dates[0];const dsince=since?Math.round((Date.now()-new Date(since))/864e5):0;
 g('Client since',since?fd(since):'—',since?dsince+' days':'');
 const last=dates[dates.length-1];g('Last order',last?fd(last):'—',last?Math.round((Date.now()-new Date(last))/864e5)+' days ago':'');
 const open=rows.filter(r=>r.status!=='Delivered'&&Number(r.stage||1)<9),done=rows.length-open.length;const pct=rows.length?Math.round(100*done/rows.length):0;
 const ring=document.createElement('span');ring.className='ring2';const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 44 44');const R=18,C=2*Math.PI*R;const c1=document.createElementNS(ns,'circle');c1.setAttribute('cx',22);c1.setAttribute('cy',22);c1.setAttribute('r',R);c1.setAttribute('fill','none');c1.setAttribute('stroke','#1E1C19');c1.setAttribute('stroke-width',3);const c2=document.createElementNS(ns,'circle');c2.setAttribute('cx',22);c2.setAttribute('cy',22);c2.setAttribute('r',R);c2.setAttribute('fill','none');c2.setAttribute('stroke',GOLD[0]);c2.setAttribute('stroke-width',3);c2.setAttribute('stroke-dasharray',C);c2.setAttribute('stroke-dashoffset',C*(1-pct/100));c2.setAttribute('transform','rotate(-90 22 22)');svg.appendChild(c1);svg.appendChild(c2);ring.appendChild(svg);ring.appendChild(document.createTextNode(pct+'%'));
