function countUp(el,text){if(RM||counted.has(el)){el.textContent=text;return;}counted.add(el);const m=/^(₹?)([\d,]+)(.*)$/.exec(text);if(!m){el.textContent=text;return;}const target=Number(m[2].replace(/,/g,''));const t0=performance.now(),dur=900;el.classList.add('count');const step=now=>{const p=Math.min(1,(now-t0)/dur),e=1-Math.pow(1-p,3);el.textContent=m[1]+fmt(Math.round(target*e))+m[3];if(p<1)requestAnimationFrame(step);};requestAnimationFrame(step);}
